public T readFrom(Class<T> clazz, Type t, Annotation[] a, MediaType mt,
                   MultivaluedMap<String, String> headers, InputStream is) throws IOException {
    if (is == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }

    // Create a fresh parser for each request to avoid cross‑thread state.
    Parser parser = ATOM_ENGINE.getParser();

    // Configure parser options securely before any parsing occurs.
    ParserOptions options = parser.getDefaultParserOptions();
    if (options == null) {
        options = new ParserOptions();
    }
    options.setAutodetectCharset(autodetectCharset);
    // Disable entity resolution and expansion to mitigate XXE.
    options.setResolveEntities(false);
    options.setExpandEntityReferences(false);
    // Explicitly forbid DTD processing if the underlying parser supports it.
    options.setAllowDoctypeDeclarations(false);

    // Apply the hardened options to the parser.
    parser.setParserOptions(options);

    // Parse the stream using the hardened configuration.
    Document<T> doc = parser.parse(is);
    return doc.getRoot();
}
