public static File allocateFile(File dir, String name) {
    if (dir == null) throw new IllegalArgumentException("dir is null");
    if (name == null) throw new IllegalArgumentException("name is null");
    // strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // Normalize name: remove any leading separators
    name = name.replaceAll("[/\\\\]+", "/"); // unify
    // Reject path traversal components
    if (name.contains("..") || name.startsWith("/") || name.startsWith("\\") ) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }
    // Resolve file
    File file = new File(dir, name);
    try {
        String canonicalDir = dir.getCanonicalPath();
        String canonicalFile = file.getCanonicalPath();
        if (!canonicalFile.startsWith(canonicalDir + File.separator)) {
            throw new IllegalArgumentException("Invalid file name: escapes target directory");
        }
    } catch (IOException e) {
        throw new IllegalStateException("Failed to resolve file path", e);
    }

    // Determine prefix/suffix based on original name (without path)
    String simpleName = new File(name).getName(); // just filename
    int dot = simpleName.lastIndexOf('.');
    String prefix = dot < 0 ? simpleName : simpleName.substring(0, dot);
    String suffix = dot < 0 ? "" : simpleName.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        file = new File(dir, newName);
        try {
            String canonicalFile2 = file.getCanonicalPath();
            if (!canonicalFile2.startsWith(canonicalDir + File.separator)) {
                throw new IllegalArgumentException("Generated file escapes target directory");
            }
        } catch (IOException e) {
            throw new IllegalStateException("Failed to resolve generated file path", e);
        }
    }
    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories for file: " + parent);
    }
    return file;
}

