     *
     * <p>The method sanitises {@code name} to prevent path‑traversal (e.g. {@code "../"}),
     * strips any URL‑style query part, and ensures that the final resolved path
     * is a descendant of {@code dir}.  If a file with the desired name already
     * exists, a numeric suffix is added (e.g. {@code name-2.ext}) until an
     * unused name is found.</p>
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the requested file name (must not be {@code null})
     * @return a {@link File} that safely resides inside {@code dir}
     * @throws IllegalArgumentException if {@code dir} or {@code name} is {@code null},
     *                                  or if {@code name} would escape {@code dir}
     * @throws IllegalStateException    if the required directories cannot be created
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        /* --------------------------------------------------------------------
         * 1. Strip any query component (e.g. "file.txt?foo=bar").
         * -------------------------------------------------------------------- */
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        /* --------------------------------------------------------------------
         * 2. Resolve the requested path against the target directory and verify
         *    that it does not escape the directory (prevents "../" attacks).
         * -------------------------------------------------------------------- */
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath;
