public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // -----------------------------------------------------------------------
    //  Token validation (RFC 7230, section 3.2.6)
    // -----------------------------------------------------------------------
    // token = 1*tchar
    // tchar = "!" / "#" / "$" / "%" / "&" / "'" / "*" / "+" / "-" / "."
    //       / "^" / "_" / "`" / "|" / "~" / DIGIT / ALPHA
    // The wildcard character '*' is also permitted for media‑type wildcards.
    // -----------------------------------------------------------------------
    private static final boolean[] ALLOWED_TOKEN_CHAR = new boolean[128];

    static {
        // ALPHA
        for (char c = 'a'; c <= 'z'; c++) ALLOWED_TOKEN_CHAR[c] = true;
        for (char c = 'A'; c <= 'Z'; c++) ALLOWED_TOKEN_CHAR[c] = true;
        // DIGIT
        for (char c = '0'; c <= '9'; c++) ALLOWED_TOKEN_CHAR[c] = true;
        // tchar symbols
        char[] symbols = {'!', '#', '$', '%', '&', '\'', '*', '+', '-', '.',
                          '^', '_', '`', '|', '~'};
        for (char c : symbols) ALLOWED_TOKEN_CHAR[c] = true;
        // Explicitly allow the wildcard '*'
        ALLOWED_TOKEN_CHAR['*'] = true;
    }

    /**
     * Validates that the supplied string conforms to the token definition
     * required for media‑type major and subtype values.
     *
     * @param str the string to validate; may be {@code null}
     * @return {@code true} if the string is a non‑empty token consisting only
     *         of allowed characters; {@code false} otherwise
