public String getForwardPage(HttpServletRequest request) {
    String pathInfo = request.getPathInfo();
    if (pathInfo == null) {
        return "Home.jsp";
    }
    // Remove leading slash
    String normalized = pathInfo;
    try {
        // Use java.nio.file.Paths to normalize
        java.nio.file.Path p = java.nio.file.Paths.get(pathInfo).normalize();
        normalized = p.toString();
    } catch (Exception e) {
        // fallback
        normalized = pathInfo;
    }
    // Remove any leading slash
    if (normalized.startsWith("/") || normalized.startsWith("\\")) {
        normalized = normalized.substring(1);
    }
    // Disallow traversal patterns
    if (normalized.contains("..") || normalized.contains("/") || normalized.contains("\\")) {
        // If contains subdirectories, reject
        return "Home.jsp";
    }
    // Validate against whitelist
    if (ALLOWED_PAGES.contains(normalized)) {
        return normalized;
    }
    return "Home.jsp";
}

