    int position = 0;
    final int total = out.length;
    // optional iteration limit to avoid DoS: maxIterations = total * 2 (worst case each iteration writes at least 1 byte)
    final long maxIterations = (long) total * 2 + 10; // safety margin
    long iterations = 0;
    while (position < total) {
        if (iterations++ > maxIterations) {
            throw new IOException("Decompression exceeded expected iteration count, possible malformed input");
        }
        int n = in.read();
        if (n == -1) {
            throw new EOFException("Unexpected end of stream while reading control byte");
        }
        if (n > 128) {
            int repeatCount = n & 0x7f;
            int value = in.read();
            if (value == -1) {
                throw new EOFException("Unexpected end of stream while reading repeat value");
            }
            if (repeatCount == 0) {
                continue; // nothing to write
            }
            if (position + repeatCount > total) {
                throw new IOException("Decompression overflow: repeat count exceeds output buffer");
            }
            for (int i = 0; i < repeatCount; i++) {
                out[position++] = (byte) value;
            }
        } else {
