/**
 * Patched version of {@code ResourceServlet} with strict validation of the
 * {@code resourceUrl} parameter to prevent directory‑traversal attacks.
 *
 * <p>The new implementation:
 * <ul>
 *   <li>Normalises each tokenised URL using {@link java.nio.file.Path#normalize()}
 *       and rejects any path that resolves to a location outside the web‑application
 *       root (i.e. contains {@code ".."} after normalisation).</li>
 *   <li>When the servlet container can resolve the physical file system location
 *       (via {@code ServletContext#getRealPath}), the canonical path is compared
 *       against the canonical root of the web‑application to guarantee that the
 *       resource resides inside the allowed directory tree.</li>
 *   <li>Retains the original {@code allowedResources} pattern check but performs it
 *       after the traversal validation.</li>
 *   <li>Provides clear error messages and fails fast with {@link ServletException}
 *       when an unsafe path is detected.</li>
 * </ul>
 *
 * <p>This patch is compatible with Java 8.
 */
@SuppressWarnings("serial")
@Deprecated
public class ResourceServlet extends HttpServletBean {

    public static final String RESOURCE_URL_DELIMITERS = ",; \t\n";
    private String allowedResources;
    private String contentType;
    private PathMatcher pathMatcher;

    // ---------------------------------------------------------------------
    // Patched method
    // ---------------------------------------------------------------------

    /**
     * Include the specified resource via the {@link RequestDispatcher}.
     *
     * @param request      current HTTP request
     * @param response     current HTTP response
     * @param resourceUrl  the URL(s) of the target resource(s)
     * @throws ServletException if the resource is not allowed or a dispatcher error occurs
     * @throws IOException      if an I/O error occurs while including the resource
     */
    private void doInclude(HttpServletRequest request,
                           HttpServletResponse response,
                           String resourceUrl) throws ServletException, IOException {

        if (resourceUrl == null || resourceUrl.trim().isEmpty()) {
            // Nothing to include – treat as a no‑op.
            return;
        }

        // Set the response content type if configured.
        if (this.contentType != null) {
            response.setContentType(this.contentType);
        }

        // Tokenise the incoming string (comma, semicolon, whitespace, etc.).
        String[] resourceUrls = StringUtils.tokenizeToStringArray(resourceUrl, RESOURCE_URL_DELIMITERS);

        // Resolve the canonical path of the web‑application root once.
        String contextRootPath = request.getServletContext().getRealPath("/");
        Path contextRootCanonical = null;
        if (contextRootPath != null) {
            contextRootCanonical = Paths.get(contextRootPath).toRealPath().normalize();
        }

        for (String url : resourceUrls) {
            // -----------------------------------------------------------------
            // 1. Basic traversal check – reject any path that resolves to ".."
            // -----------------------------------------------------------------
            if (containsPathTraversal(url)) {
                throw new ServletException("Resource URL [" + url + "] contains prohibited path traversal sequences.");
