            // -----------------------------------------------------------------
            if (this.allowedResources != null && !this.pathMatcher.match(this.allowedResources, url)) {
                throw new ServletException("Resource [" + url + "] does not match allowed pattern [" + this.allowedResources + "]");
            }

            // -----------------------------------------------------------------
            // 3. Physical‑path validation (when the container can resolve it)
            // -----------------------------------------------------------------
            if (contextRootCanonical != null) {
                String realPath = request.getServletContext().getRealPath(url);
                if (realPath != null) {
                    Path targetCanonical = Paths.get(realPath).toRealPath().normalize();
                    if (!targetCanonical.startsWith(contextRootCanonical)) {
                        throw new ServletException("Resource [" + url + "] resolves outside the web application directory.");
                    }
                }
