import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.charset.CharsetEncoder;
import java.nio.charset.CoderResult;

/**
 * Fixed implementation of {@link ZipEncoding} that guarantees termination.
 *
 * <p>The original implementation could enter an infinite loop when the
 * {@link CharsetEncoder} returned {@code UNDERFLOW} while there were still
 * characters left in the input buffer (e.g. an incomplete surrogate pair) or
 * when an error result reported a length of {@code 0}.  The new version
 * explicitly handles these cases, guarantees that the input position always
 * advances, and imposes a retry limit to protect against pathological inputs.
 *
 * <p>The method is compatible with Java 7.
 */
class NioZipEncoding implements ZipEncoding, CharsetAccessor {

    // -----------------------------------------------------------------------
    // other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    @Override
    public ByteBuffer encode(final String name) {
        final CharsetEncoder enc = newEncoder();
        final CharBuffer cb = CharBuffer.wrap(name);
        CharBuffer tmp = null;

        // Initial buffer – size is estimated safely by the helper method.
        ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

        // A safety counter – prevents pathological inputs from looping forever.
        final int MAX_RETRIES = 1000;
        int retryCount = 0;

        while (cb.remaining() > 0) {
            final CoderResult res = enc.encode(cb, out, false);

            // -------------------------------------------------------------------
            // 1. Normal termination – the encoder cannot consume more input now.
            // -------------------------------------------------------------------
            if (res.isUnderflow()) {
                // No progress can be made without more input; break to avoid
                // an endless loop (the remaining characters will be processed by
                // the final encode call after the loop).
                break;
            }

            // ---------------------------------------------------------------
            // 2. Output buffer overflow – grow the buffer and retry.
            // ---------------------------------------------------------------
            if (res.isOverflow()) {
                final int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
                out = ZipEncodingHelper.growBufferBy(out, increment);
                // Reset retry counter because we made progress (the buffer grew).
                retryCount = 0;
                continue;
            }

            // ---------------------------------------------------------------
            // 3. Unmappable or malformed input – replace with a surrogate.
            // ---------------------------------------------------------------
            if (res.isUnmappable() || res.isMalformed()) {
                int errorLength = res.length();

                // Defensive: some encoders may report a length of 0, which would
                // otherwise cause an infinite loop because the input position
                // would never advance.
                if (errorLength <= 0) {
                    errorLength = 1;
                }

                // Ensure there is enough space for the surrogate representation.
                final int spaceForSurrogate = estimateIncrementalEncodingSize(enc, 6 * errorLength);
                if (spaceForSurrogate > out.remaining()) {
                    // Compute a safe extra size based on the remaining characters.
                    int charCount = 0;
                    for (int i = cb.position(); i < cb.limit(); i++) {
                        charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                    }
                    final int totalExtraSpace = estimateIncrementalEncodingSize(enc, charCount);
                    out = ZipEncodingHelper.growBufferBy(out, totalExtraSpace - out.remaining());
                }

                if (tmp == null) {
                    tmp = CharBuffer.allocate(6);
                }

                // Replace each problematic character with its escaped surrogate.
