                    final char ch = cb.get(); // advances the input position
                    out = encodeFully(enc, encodeSurrogate(tmp, ch), out);
                }

                // Reset the retry counter because we have made forward progress.
                retryCount = 0;
                continue;
            }

            // ---------------------------------------------------------------
            // 4. Unexpected result – count retries and abort if we exceed limit.
            // ---------------------------------------------------------------
            retryCount++;
            if (retryCount > MAX_RETRIES) {
                throw new IllegalStateException(
                        "Encoding failed to make progress after " + MAX_RETRIES + " attempts for input: " + name);
            }
        }

        // -----------------------------------------------------------------------
        // Final encoding step – flush any remaining characters.
        // -----------------------------------------------------------------------
        enc.encode(cb, out, true);
        out.limit(out.position());
        out.rewind();
        return out;
