private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory, Object principal, Object credentials) throws NamingException {
    // Validate inputs
    if (principal == null || credentials == null) {
        throw new IllegalArgumentException("Principal and credentials must not be null");
    }
    if (!(principal instanceof String) || !(credentials instanceof String)) {
        throw new IllegalArgumentException("Principal and credentials must be strings");
    }

    JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    try {
        ctx = new InitialLdapContext(env, null);
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        // negotiate TLS with default SSL context; could be customized
        tls.negotiate();

        // Set authentication credentials after TLS is established
        ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
        ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
        ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

        // Force a bind with the supplied credentials
        ctx.reconnect(null);

        // Optionally verify bind succeeded by a harmless operation
        ctx.getAttributes(""); // root DSE

        return ctx;
    } catch (IOException e) {
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s", server(jndiLdapContextFactory), e.getMessage()));
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException e) {
        // Ensure any authentication failures are logged without leaking credentials
        securityLog.warn(withRealm("LDAP authentication failed for user '%s' on server '%s': %s", principal, server(jndiLdapContextFactory), e.getMessage()));
        throw e;
    } finally {
        // Close TLS response if it was created and authentication failed (ctx may be null)
        if (tls != null) {
            try {
                tls.close();
            } catch (IOException ignored) {
                // ignore close errors
            }
        }
        // If we are not returning a successfully bound context, close it
        // The caller expects a bound context; if an exception occurred, ctx will be closed here.
        if (ctx != null && !(ctx instanceof LdapContext && ctx.getEnvironment().containsKey(Context.SECURITY_PRINCIPAL))) {
            // Not bound, close
            LdapUtils.closeContext(ctx);
        }
    }
}

