    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    boolean bindSucceeded = false;

    try {
        // 1. Create an anonymous context
        ctx = new InitialLdapContext(env, null);

        // 2. Upgrade the connection to TLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        tls.negotiate(); // uses the default SSLContext; can be customised if needed

        // 3. Supply authentication data *after* TLS is established
        ctx.addToEnvironment(Context.SECURITY_AUTHENTICATION,
                             jndiLdapContextFactory.getAuthenticationMechanism());
        ctx.addToEnvironment(Context.SECURITY_PRINCIPAL, principal);
        ctx.addToEnvironment(Context.SECURITY_CREDENTIALS, credentials);

        // 4. Force a bind with the supplied credentials
        ctx.reconnect(null);

        // 5. Perform a harmless operation to ensure the bind really succeeded
        ctx.getAttributes(""); // reads the Root DSE

        bindSucceeded = true; // everything succeeded, return the bound context
        return ctx;
    } catch (IOException e) {
        // TLS negotiation failed – log without exposing credentials
        securityLog.error(withRealm("Failed to negotiate TLS connection with '%s': %s",
                                   server(jndiLdapContextFactory), e.getMessage()));
        throw new CommunicationException(e.getMessage(), e);
    } catch (NamingException e) {
        // Authentication or other LDAP error – log at WARN level, omit credentials
        securityLog.warn(withRealm("LDAP authentication failed for user '%s' on server '%s': %s",
                                   principal, server(jndiLdapContextFactory), e.getMessage()));
        throw e;
    } finally {
        // Close TLS layer if it was created and we are not returning a successful context
        if (!bindSucceeded && tls != null) {
            try {
                tls.close();
            } catch (IOException ignored) {
                // Ignored – we are already handling an error condition
            }
        }
        // Close the LDAP context if binding did not succeed
