    //  Whitelist of component types that are considered safe for deserialization
    // -----------------------------------------------------------------------
    private static final Set<Class<?>> ALLOWED_COMPONENT_TYPES = new HashSet<>(
            Arrays.asList(
                    // primitives (handled via their wrapper classes)
                    Boolean.class, Byte.class, Short.class, Integer.class,
                    Long.class, Float.class, Double.class, Character.class,
                    // primitive arrays
                    byte[].class,
